package com.cafeteria.controller.admin;
import com.cafeteria.dto.request.*; import com.cafeteria.dto.response.OrderResponse; import com.cafeteria.service.OrderService; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.List;
@RestController @RequestMapping("/api/admin/orders") public class AdminOrderController{private final OrderService s;public AdminOrderController(OrderService s){this.s=s;}@GetMapping public List<OrderResponse> byDate(@RequestParam(required=false)LocalDate date){return s.getOrdersByDate(date);}@GetMapping("/{id}")public OrderResponse get(@PathVariable Long id){return s.getOrderById(id);}@PatchMapping("/{id}/status")public OrderResponse status(@PathVariable Long id,@RequestBody StatusUpdateRequest r){return s.updateOrderStatus(id,r.status());}@PatchMapping("/{id}/payment")public OrderResponse payment(@PathVariable Long id,@RequestBody PaymentUpdateRequest r){return s.updatePaymentStatus(id,r.status(),r.method());}}
